# Validation regression tests for ClinicoPath::jwaffle
# Generated by /validate-function jwaffle depth=exhaustive (2026-11-24)
# Passing claims are live tests; confirmed open defects carry the correct
# expectation guarded by skip("VAL-jwaffle-NN open defect: ...").

jw_build_plot <- function(data, ..., via_wrapper = TRUE) {
    args <- list(...)
    d2 <- data
    if (via_wrapper) {
        if (!is.null(args$groups) && args$groups %in% names(d2))
            d2[[args$groups]] <- as.factor(d2[[args$groups]])
        if (!is.null(args$facet) && args$facet %in% names(d2))
            d2[[args$facet]] <- as.factor(d2[[args$facet]])
    }
    opt <- do.call(ClinicoPath:::jwaffleOptions$new, args)
    a <- ClinicoPath:::jwaffleClass$new(options = opt, data = d2)
    a$init()
    suppressWarnings(suppressMessages(a$run()))
    tmp <- tempfile(fileext = ".png")
    grDevices::png(tmp, width = 700, height = 550)
    on.exit({ grDevices::dev.off(); unlink(tmp) }, add = TRUE)
    suppressWarnings(suppressMessages(a$.__enclos_env__$private$.plot(a$results$plot)))
    p <- a$.__enclos_env__$private$.cached_plot
    list(analysis = a, results = a$results, plot = p, built = ggplot2::ggplot_build(p))
}

jw_strip_html <- function(x) {
    if (is.null(x)) return("")
    gsub("<[^>]+>", "", paste(x, collapse = ""))
}

# Oracle: independent Hamilton largest-remainder apportionment to 100 squares
jw_hamilton_100 <- function(counts) {
    raw <- (counts / sum(counts)) * 100
    fl <- floor(raw)
    need <- as.integer(round(100 - sum(fl)))
    if (need > 0L) {
        idx <- utils::tail(order(raw - fl), need)
        fl[idx] <- fl[idx] + 1L
    }
    as.integer(fl)
}

# --- LIVE PASSING TESTS ---

test_that("C01: unweighted counts and percentages match exact arithmetic and base::table()", {
    # Oracle: hand arithmetic on n=12 (6/4/2 -> 50.0%, 33.3%, 16.7%) and base::table() on ClinicoPath::jwaffle_pathology
    d <- data.frame(
        grade = factor(c(rep("High", 6), rep("Medium", 4), rep("Low", 2), NA),
                       levels = c("High", "Medium", "Low"))
    )
    res <- suppressMessages(ClinicoPath::jwaffle(data = d, groups = "grade", showSummaries = TRUE))
    txt <- jw_strip_html(res$analysisSummary$content)
    expect_match(txt, "contains 12 cases", fixed = TRUE)
    expect_match(txt, "High: 50.0% (n=6)", fixed = TRUE)
    expect_match(txt, "Medium: 33.3% (n=4)", fixed = TRUE)
    expect_match(txt, "Low: 16.7% (n=2)", fixed = TRUE)

    dp <- ClinicoPath::jwaffle_pathology
    tab <- table(dp$tumor_grade, useNA = "no")
    rp <- suppressMessages(ClinicoPath::jwaffle(data = dp, groups = "tumor_grade", showSummaries = TRUE))
    tp <- jw_strip_html(rp$analysisSummary$content)
    for (nm in names(tab)) {
        pct <- sprintf("%.1f%%", 100 * as.numeric(tab[[nm]]) / sum(tab))
        expect_match(tp, sprintf("%s: %s (n=%d)", nm, pct, as.integer(tab[[nm]])), fixed = TRUE)
    }
})

test_that("C02: weighted counts aggregate duplicate rows and match tapply() on HairEyeColor", {
    # Oracle: exact arithmetic (A=20, B=40, C=20, total=80) and base::tapply() on datasets::HairEyeColor
    d <- data.frame(grp = factor(c("A", "A", "B", "C"), levels = c("A", "B", "C")),
                    wt = c(12.5, 7.5, 40.0, 20.0))
    res <- suppressMessages(ClinicoPath::jwaffle(data = d, groups = "grp", counts = "wt", showSummaries = TRUE))
    txt <- jw_strip_html(res$analysisSummary$content)
    expect_match(txt, "contains 80 weighted units", fixed = TRUE)
    expect_match(txt, "A: 25.0% (n=20)", fixed = TRUE)
    expect_match(txt, "B: 50.0% (n=40)", fixed = TRUE)
    expect_match(txt, "C: 25.0% (n=20)", fixed = TRUE)

    d_hec <- as.data.frame(datasets::HairEyeColor)
    eye_tot <- tapply(d_hec$Freq, d_hec$Eye, sum)
    rh <- suppressMessages(ClinicoPath::jwaffle(data = d_hec, groups = "Eye", counts = "Freq", showSummaries = TRUE))
    th <- jw_strip_html(rh$analysisSummary$content)
    for (nm in names(eye_tot)) {
        pct <- sprintf("%.1f%%", 100 * as.numeric(eye_tot[[nm]]) / sum(eye_tot))
        expect_match(th, sprintf("%s: %s (n=%g)", nm, pct, as.numeric(eye_tot[[nm]])), fixed = TRUE)
    }
})

test_that("C03 & C07: faceted per-panel percentages, grand total, and strip labels match exact sums", {
    # Oracle: hand arithmetic on 2-arm dataset (Placebo n=10: 20/60/20; Drug n=20: 75/15/10; grand n=30)
    skip_if_not_installed("waffle")
    skip_if_not_installed("ggplot2")
    d <- data.frame(
        resp = factor(c(rep("Resp", 2), rep("Stable", 6), rep("Prog", 2),
                        rep("Resp", 15), rep("Stable", 3), rep("Prog", 2)),
                      levels = c("Resp", "Stable", "Prog")),
        arm  = factor(c(rep("Placebo", 10), rep("Drug", 20)), levels = c("Placebo", "Drug"))
    )
    bp <- jw_build_plot(d, groups = "resp", facet = "arm", showSummaries = TRUE, show_legend = TRUE)
    txt <- jw_strip_html(bp$results$analysisSummary$content)
    expect_match(txt, "Among arm Placebo (n=10): resp Resp: 20.0% (n=2); resp Stable: 60.0% (n=6); resp Prog: 20.0% (n=2)", fixed = TRUE)
    expect_match(txt, "Among arm Drug (n=20): resp Resp: 75.0% (n=15); resp Stable: 15.0% (n=3); resp Prog: 10.0% (n=2)", fixed = TRUE)
    expect_match(txt, "Overall Sample: 30 cases showing resp distribution across 2 arm groups", fixed = TRUE)

    g <- ggplot2::ggplotGrob(bp$plot)
    strips <- as.character(stats::na.omit(unlist(lapply(
        g$grobs[grepl("strip", g$layout$name)],
        function(s) tryCatch(s$grobs[[1]]$children[[2]]$children[[1]]$label, error = function(e) NA_character_)
    ))))
    expect_equal(strips, c("Placebo (n=10)", "Drug (n=20)"))
})

