test_that("C11: degenerate inputs (empty, all-NA, 1-cat, negative, Inf, zero-sum, factor-with-values) are rejected", {
    # Oracle: input validation contract in R/jwaffle.b.R
    expect_error(ClinicoPath::jwaffle(data = data.frame(g = factor(character(0), levels = c("A", "B"))), groups = "g"))
    expect_error(ClinicoPath::jwaffle(data = data.frame(g = factor(rep(NA, 5), levels = c("A", "B"))), groups = "g"))
    expect_error(ClinicoPath::jwaffle(data = data.frame(g = factor(rep("Only", 20))), groups = "g"))
    expect_error(ClinicoPath::jwaffle(data = data.frame(g = factor(c("A", "B")), w = c(10, -1)), groups = "g", counts = "w"), "negative")
    expect_error(ClinicoPath::jwaffle(data = data.frame(g = factor(c("A", "B")), w = c(10, Inf)), groups = "g", counts = "w"), "non-finite")
    expect_error(ClinicoPath::jwaffle(data = data.frame(g = factor(c("A", "B")), w = c(0, 0)), groups = "g", counts = "w"), "zero")

    f_nom <- factor(c("10", "30", "60"), levels = c("10", "30", "60"))
    attr(f_nom, "values") <- c(10L, 30L, 60L)
    expect_error(ClinicoPath::jwaffle(data = data.frame(g = factor(c("A", "B", "C")), w = f_nom),
                                      groups = "g", counts = "w"), "numeric")
})

