test_that("C16: metamorphic invariants hold (row permutation, rescaling weights, duplicating rows, level order)", {
    # Oracle: mathematical invariance of proportions under row permutation, scaling, and replication
    skip_if_not_installed("waffle")
    skip_if_not_installed("ggplot2")
    set.seed(20260101)
    d <- data.frame(
        g = factor(c(rep("G1", 25), rep("G2", 45), rep("G3", 30)), levels = c("G1", "G2", "G3")),
        w = c(rep(2, 25), rep(1.5, 45), rep(3, 30))
    )
    b0 <- jw_build_plot(d, groups = "g", counts = "w", showSummaries = TRUE)
    bp <- jw_build_plot(d[sample(nrow(d)), ], groups = "g", counts = "w", showSummaries = TRUE)
    expect_identical(bp$results$analysisSummary$content, b0$results$analysisSummary$content)

    d10 <- d; d10$w <- d10$w * 10
    b10 <- jw_build_plot(d10, groups = "g", counts = "w", showSummaries = TRUE)
    sq0 <- as.integer(table(factor(b0$built$data[[1]]$fill, levels = unique(b0$built$data[[1]]$fill))))
    sq10 <- as.integer(table(factor(b10$built$data[[1]]$fill, levels = unique(b10$built$data[[1]]$fill))))
    expect_equal(sq10, sq0)

    bdup <- jw_build_plot(rbind(d, d), groups = "g", counts = "w", showSummaries = TRUE)
    sqdup <- as.integer(table(factor(bdup$built$data[[1]]$fill, levels = unique(bdup$built$data[[1]]$fill))))
    expect_equal(sqdup, sq0)
})

test_that("C17 & C19: special/non-ASCII names and asSource() round-trip cleanly", {
    # Oracle: parseable R syntax reproducing identical analysisSummary
    d <- data.frame(
        check.names = FALSE,
        `Gréade sc` = factor(c(rep("<5 mm", 25), rep("A & B (1/2)", 75)), levels = c("<5 mm", "A & B (1/2)")),
        `Arm "1" / A+B` = factor(c(rep("Cohort <1>", 50), rep("Cohort &2", 50)), levels = c("Cohort <1>", "Cohort &2"))
    )
    opt <- ClinicoPath:::jwaffleOptions$new(
        groups = "Gréade sc", facet = 'Arm "1" / A+B', rows = 10, flip = TRUE,
        mytitle = 'Pathology "Waffle" \\ Test', showSummaries = TRUE, show_legend = TRUE
    )
    a <- ClinicoPath:::jwaffleClass$new(options = opt, data = d)
    a$init()
    a$run()
    src <- a$asSource()
    expect_silent(parsed <- parse(text = src))
    data <- d
    res2 <- eval(parsed)
    expect_identical(res2$analysisSummary$content, a$results$analysisSummary$content)
})

