test_that("C09 (VAL-jwaffle-03): vanishing-category warning matches exact per-panel zero-square apportionment", {
    # Oracle: exact comparison against rendered ggplot_build fill set per panel
    skip_if_not_installed("waffle")
    skip_if_not_installed("ggplot2")
    # Unfaceted FN: 0.6% gets 0 squares under Hamilton
    d_fn <- data.frame(g = factor(c("A", "B", "C", "Rare06"), levels = c("A", "B", "C", "Rare06")),
                       w = c(338, 338, 318, 6))
    r_fn <- ClinicoPath::jwaffle(data = d_fn, groups = "g", counts = "w")
    expect_match(r_fn$notices$content, "missing from the chart", fixed = TRUE)

    # Unfaceted FP: 0.4% gets 1 square under Hamilton
    d_fp <- data.frame(g = factor(c("A", "B", "C", "D", "E", "Rare04"),
                                  levels = c("A", "B", "C", "D", "E", "Rare04")),
                       w = c(201, 201, 201, 201, 192, 4))
    r_fp <- ClinicoPath::jwaffle(data = d_fp, groups = "g", counts = "w")
    expect_false(grepl("missing from the chart", r_fp$notices$content, fixed = TRUE))

    # Faceted FN: 0.2% in Arm1 (5.1% overall)
    d_fac <- data.frame(
        g = factor(c("A", "B", "RareSub", "A", "B", "RareSub"), levels = c("A", "B", "RareSub")),
        arm = factor(c("Arm1", "Arm1", "Arm1", "Arm2", "Arm2", "Arm2"), levels = c("Arm1", "Arm2")),
        w = c(600, 398, 2, 500, 400, 100)
    )
    r_fac <- ClinicoPath::jwaffle(data = d_fac, groups = "g", facet = "arm", counts = "w")
    expect_match(r_fac$notices$content, "missing from the chart", fixed = TRUE)
    expect_match(r_fac$notices$content, "Arm1", fixed = TRUE)

    # Faceted FP: 30% in SmallArm (0.3% overall) IS drawn (30 squares) -> no warning
    d_fac_fp <- data.frame(
        g = factor(c("A", "B", "LocalMajor", "A", "B"), levels = c("A", "B", "LocalMajor")),
        arm = factor(c("SmallArm", "SmallArm", "SmallArm", "BigArm", "BigArm"),
                     levels = c("SmallArm", "BigArm")),
        w = c(4, 3, 3, 600, 400)
    )
    r_fac_fp <- ClinicoPath::jwaffle(data = d_fac_fp, groups = "g", facet = "arm", counts = "w")
    expect_false(grepl("missing from the chart", r_fac_fp$notices$content, fixed = TRUE))
})

