    # Oracle: 0-count cell has no observations rounded away (only count > 0 & squares == 0 vanishes)
    d <- data.frame(
        g   = factor(c("A", "B", "C", "A", "B", "C"), levels = c("A", "B", "C")),
        arm = factor(c("Arm1", "Arm1", "Arm1", "Arm2", "Arm2", "Arm2"), levels = c("Arm1", "Arm2")),
        w   = c(60, 40, 0, 50, 30, 20)
    )
    r <- ClinicoPath::jwaffle(data = d, groups = "g", facet = "arm", counts = "w")
    expect_false(grepl("missing from the chart", r$notices$content, fixed = TRUE))
})

test_that("IR-jwaffle-04: overflowing finite weights report non-finite overflow rather than 'sums to zero'", {
    # Oracle: 1e308 + 1e308 = Inf (overflow, not zero)
    d <- data.frame(g = factor(c("A", "B")), w = c(1e308, 1e308))
    err <- tryCatch({ ClinicoPath::jwaffle(data = d, groups = "g", counts = "w"); NA_character_ },
                    error = conditionMessage)
    expect_false(is.na(err))
    expect_match(err, "overflow|non-finite", ignore.case = TRUE)
    expect_false(grepl("sums to zero", err, fixed = TRUE))
})

test_that("IR-jwaffle-05: invalid in-place data edit rejects cleanly and invalidates cached plot without blanking panels before reject()", {
    # Oracle: jamovi greys results over reject(); cached plot is invalidated and normal
    # early return (groups = NULL) clears stale analysisSummary.
    d <- data.frame(g = factor(c(rep("A", 30), rep("B", 70)), levels = c("A", "B")), w = rep(1, 100))
    opt <- ClinicoPath:::jwaffleOptions$new(groups = "g", counts = "w", showSummaries = TRUE)
    a <- ClinicoPath:::jwaffleClass$new(options = opt, data = d)
    a$init()
    a$run()
    expect_true(nzchar(a$results$analysisSummary$content))
    a$.__enclos_env__$private$.cached_plot <- "sentinel"
    a$.__enclos_env__$private$.data$w[100] <- -5
    expect_error(a$.__enclos_env__$private$.run(), "negative")
    expect_null(a$.__enclos_env__$private$.cached_plot)

    # Normal early return (groups cleared) blanks stale summary
    a$options$option("groups")$value <- NULL
    a$.__enclos_env__$private$.run()
    expect_identical(a$results$analysisSummary$content, "")
})

test_that("SEC-jwaffle-01: asSource() escapes quote-breaking strings, drops undeclared options and list values", {
    d <- data.frame(g = factor(c("A", "B", "A", "B")))
    payload <- "default\", flip = {stop(\"X\"); TRUE}, mytitle = \"x"
    for (opt_name in c("color_palette", "rows", "show_legend", "mytitle", "legendtitle")) {
        a <- ClinicoPath:::jwaffleClass$new(
            options = ClinicoPath:::jwaffleOptions$new(groups = "g"),
            data = d
        )
        o <- a$options$option(opt_name)
        o$value <- payload
        ex <- parse(text = a$asSource())[[1]]
        expect_identical(ex[[opt_name]], payload)
        expect_false("flip" %in% names(ex))
    }

    # Undeclared option name injected from a saved .omv/.omt is dropped
    a2 <- ClinicoPath:::jwaffleClass$new(
        options = ClinicoPath:::jwaffleOptions$new(groups = "g"),
        data = d
    )
    a2$options$.addOption(jmvcore:::Option$new(
        "color_palette = \"dark\", flip = {stop(\"X\"); TRUE}, showSummaries", FALSE
    ))
    ex2 <- parse(text = a2$asSource())[[1]]
    expect_identical(names(ex2)[-1], c("data", "groups"))

    # List value with quote-breaking name is dropped rather than deparsed
    a3 <- ClinicoPath:::jwaffleClass$new(
        options = ClinicoPath:::jwaffleOptions$new(groups = "g"),
        data = d
    )
    o3 <- a3$options$option("mytitle")
    o3$value <- stats::setNames(list(1), "x\" = 1), flip = {stop(1); TRUE}, legendtitle = list(\"y")
    ex3 <- parse(text = a3$asSource())[[1]]
    expect_identical(names(ex3)[-1], c("data", "groups"))
})

test_that("SEC-jwaffle-02: tidy-eval facet_wrap renders adversarial column names including backtick + function call", {
    skip_if_not_installed("waffle")
    skip_if_not_installed("ggplot2")
    fnm <- "a` + stop('x') + `b"
    d <- data.frame(check.names = FALSE, g = factor(c("A", "B", "A", "B")))
    d[[fnm]] <- factor(c("F1", "F1", "F2", "F2"))
    bp <- jw_build_plot(d, groups = "g", facet = fnm, via_wrapper = FALSE)
    expect_equal(nrow(bp$built$layout$layout), 2L)
})

test_that("SEC-jwaffle-03: rows < 1 backstop rejects even under init(noThrow=TRUE) + run(noThrow=TRUE)", {
    d <- data.frame(g = factor(c("A", "B", "A", "B")))
    a <- ClinicoPath:::jwaffleClass$new(
        options = ClinicoPath:::jwaffleOptions$new(groups = "g"),
        data = d
    )
    o <- a$options$option("rows")
    o$value <- 0L
    a$init(noThrow = TRUE)
    a$run(noThrow = TRUE)
    expect_match(a$results$todo$content, "positive integer", fixed = TRUE)
})
